62: function treat(){const s=selectedSlime();if(state.dew<1){toast('No dew left — try a little adventure!');return;}state.dew--;s.mood=Math.min(100,s.mood+16);s.xp+=5;if(!state.questDone){state.questDone=true;state.glow+=15;toast(`${s.name} loved that! Task complete · +15 glow`);}else toast(`${s.name} is looking very happy! +5 XP`);if(s.xp>=50){s.xp-=50;s.level++;s.maxHp+=5;s.hp=Math.min(s.maxHp,s.hp+5);s.atk++;toast(`${s.name} grew to level ${s.level}!`);}render();}
