64: function craft(){if(state.recipe.length!==2){toast('Choose two ingredients first.');return;}if(state.glow<45||state.dew<3){toast('You need 45 glow and 3 dew to craft.');return;}state.glow-=45;state.dew-=3;const a=ingredients[state.recipe[0]],b=ingredients[state.recipe[1]];const avg=new THREE.Color(a.color).lerp(new THREE.Color(b.color),.5);const color='#'+avg.getHexString();const chosen=ingredients[state.recipe[Math.floor(Math.random()*2)]];const name=chosen.kind==='Mossling'?'Fern':chosen.kind==='Dewdrop'?'Bloop':chosen.kind==='Cinder'?'Cinder':chosen.kind==='Starlit'?'Nova':'Button';const slime={id:Date.now(),name,kind:chosen.kind,color,element:chosen.element,rarity:'COMMON',hp:chosen.hp,maxHp:chosen.hp,atk:chosen.atk,level:1,xp:0,mood:76,energy:100};state.slimes.push(slime);state.selected=state.slimes.length-1;toast(`${name} the ${chosen.kind} joined your family!`);render();}
