66: function enemyTurn(message){const s=selectedSlime();const hit=3+Math.floor(Math.random()*5);s.hp=Math.max(0,s.hp-hit);state.battle.round++;state.battle.message=`${message} The ${zones[state.battle.zone].foe} booped back for ${hit}!`;if(s.hp===0){s.hp=Math.ceil(s.maxHp*.55);state.battle.message=`${s.name} needs a little rest. They came home safely.`;state.battle.enemyHp=zones[state.battle.zone].hp;state.battle.won=false;setTimeout(()=>{if(state.battle){state.battle=null;render();toast(`${s.name} is resting at home.`);}},1200);}}
67: function attack(power=0){const b=state.battle;if(!b||b.enemyHp<=0)return;const s=selectedSlime();b.enemyHp=Math.max(0,b.enemyHp-s.atk-power);s.hp=Math.max(1,s.hp);s.xp+=6+power;if(b.enemyHp<=0){b.message=`${s.name} won the little scuffle!`;b.won=true;}else enemyTurn(`${s.name} gave a ${power?'sparkly':'gentle'} boop!`);render();}
68: function claimReward(){const b=state.battle;if(!b)return;const z=zones[b.zone];const s=selectedSlime();state.glow+=z.reward;state.dew+=z.dew;state.wins++;s.hp=Math.min(s.maxHp,s.hp+10);s.energy=Math.min(100,s.energy+8);if(s.xp>=50){s.xp-=50;s.level++;s.maxHp+=5;s.hp=s.maxHp;s.atk++;}state.battle=null;state.day++;toast(`Journey complete! +${z.reward} glow, +${z.dew} dew`);render();}
