  group.userData.phase=Math.random()*6.28;group.userData.data=data;return group;
 }
 spawnBurst(){
  const origin=this.slime.position,color=this.slime.userData.data.color;
  const ring=new THREE.Mesh(new THREE.TorusGeometry(.36,.025,8,36),new THREE.MeshBasicMaterial({color:'#fff2bd',transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.set(origin.x,.058,origin.z);this.scene.add(ring);this.effects.push({mesh:ring,life:0,max:.62,ring:true});
  for(let i=0;i<11;i++){const dot=new THREE.Mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.035,0),new THREE.MeshBasicMaterial({color:i%3===0?'#fff3b7':color,transparent:true}));dot.position.set(origin.x+(Math.random()-.5)*.8,.22+Math.random()*.55,origin.z+(Math.random()-.5)*.65);this.scene.add(dot);this.effects.push({mesh:dot,life:0,max:.55+Math.random()*.35,vy:1+Math.random()*1.7,vx:(Math.random()-.5)*1.5,vz:(Math.random()-.5)*1.2});}
