23: function localizeText(value){let text=value;for(const [en,ko] of Object.entries(koText).sort(([a],[b])=>b.length-a.length))text=text.split(en).join(ko);return text;}
24: function localizeDOM(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(node.nodeValue.trim())node.nodeValue=localizeText(node.nodeValue);}root.querySelectorAll('[aria-label],[title],[placeholder]').forEach(el=>{for(const attr of ['aria-label','title','placeholder'])if(el.hasAttribute(attr))el.setAttribute(attr,localizeText(el.getAttribute(attr)));});}
