function startBattle(){if(state.battle){toast('Finish your current journey first.');return;}const z=zones[state.zone];state.battle={zone:state.zone,enemyHp:z.hp,round:1,message:`${z.foe}이(가) 나타났어요!`,won:false};render();}
function enemyTurn(message){const s=selectedSlime();const hit=3+Math.floor(Math.random()*5);s.hp=Math.max(0,s.hp-hit);state.battle.round++;state.battle.message=`${message} ${zones[state.battle.zone].foe}이(가) ${hit}의 피해로 반격했어요!`;if(s.hp===0){s.hp=Math.ceil(s.maxHp*.55);state.battle.message=`${s.name}이(가) 잠시 쉬어야 해요. 무사히 집에 돌아왔어요.`;state.battle.enemyHp=zones[state.battle.zone].hp;state.battle.won=false;setTimeout(()=>{if(state.battle){state.battle=null;render();toast(`${s.name}은(는) 집에서 쉬고 있어요.`);}},1200);}}
function attack(power=0){const b=state.battle;if(!b||b.enemyHp<=0)return;const s=selectedSlime();b.enemyHp=Math.max(0,b.enemyHp-s.atk-power);s.hp=Math.max(1,s.hp);s.xp+=6+power;if(b.enemyHp<=0){b.message=`${s.name}이(가) 작은 싸움에서 이겼어요!`;b.won=true;}else enemyTurn(`${s.name}이(가) ${power?'반짝이는':'다정한'} 통통 공격을 했어요!`);render();}

